#!/usr/bin/env node
// bmad-generated:30f1a112
// BMAD Swarm - the TASK-LEDGER WRITER (ADR-018 / D-037 / D-049; phase2 design
// §3.3, §4.3). Generated by bmad-swarm - do not edit manually.
//
// A PostToolUse hook: a GUARANTEED, event-driven writer of the durable task
// coordination log (artifacts/context/task-ledger.md). It is the exact survival
// property D-037 is built on — machine coordination state written as a side
// effect of the tool call, with NO LLM diligence in the write path. project.yaml
// died because it was a prompted chore-file (8/9 field projects lying); the
// decision-log survived because it was written by a guaranteed writer. The task
// ledger joins the survivors.
//
// Payload shapes are the ones VERIFIED LIVE on Claude Code v2.1.222
// (artifacts/exploration/spike-posttooluse-2026-08-13.md) — NOT the SDK docs,
// which are wrong about SendMessage's field names:
//   TaskCreate — tool_input {subject, description, owner?}
//                tool_response {task: {id, subject}}          => `created` (+`assigned` if owner)
//   TaskUpdate — tool_input {taskId, status?, owner?, ...}
//                tool_response {statusChange: {from, to}, updatedFields}
//                                                             => a `<status>` row (owner round-trips
//                                                                through tool_input — no re-query)
//   SendMessage — tool_input {to, summary, message}          => `woken` row, resolved by JOINING
//                 tool_response {success, ...}                   `to` against an owner->task-id map
//                                                                the hook rebuilds from the ledger.
//                 NOTE: SendMessage carries NO task_id anywhere — the `woken`
//                 signal is a DETERMINISTIC JOIN, not text-parsing of the message,
//                 and not a gate (the authoritative wake-ack is TaskUpdate ->
//                 in_progress, which is fully reliable; a stray coordination
//                 message to an owner logging a spurious `woken` is a tolerable
//                 false positive on an advisory signal — spike §2).
//
// Writes go THROUGH the pinned CLI `node .claude/bmad/bin/record.cjs task-event`
// (lock + atomic append + session binding), never by editing task-ledger.md
// directly — the ledger-write-guard would (correctly) deny a direct edit. This
// hook is one of many concurrent appenders; the CLI's directory lock serializes
// them.
//
// ALWAYS EXIT 0. This is a logging side-channel on a tool that already
// succeeded; a writer failure must NEVER wedge coordination or surface an error
// to the acting agent. Missing fields => skip silently.

const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (c) => { input += c; });
process.stdin.on('end', () => {
  let event;
  try { event = JSON.parse(input); } catch { process.exit(0); } // malformed: never wedge

  try {
    const projectRoot = process.env.CLAUDE_PROJECT_DIR || event.cwd || process.cwd();
    const contextDir = path.join(projectRoot, 'artifacts', 'context');
    const session = event.session_id || null;
    const ti = event.tool_input || {};
    const tr = event.tool_response || {};

    switch (event.tool_name) {
      case 'TaskCreate':   onTaskCreate(contextDir, session, ti, tr); break;
      case 'TaskUpdate':   onTaskUpdate(contextDir, session, ti, tr); break;
      case 'SendMessage':  onSendMessage(contextDir, session, ti, tr); break;
      default: break; // matcher should prevent this; ignore anything else
    }
  } catch { /* advisory writer: swallow everything */ }
  process.exit(0);
});

// --- event handlers --------------------------------------------------------

function onTaskCreate(contextDir, session, ti, tr) {
  const id = (tr.task && tr.task.id) || null;
  if (!id) return; // no durable row without the allocated id
  const subject = ti.subject || (tr.task && tr.task.subject) || '';
  emit(contextDir, { task: id, event: 'created', session, owner: ti.owner, detail: subject });
  // A task created already-assigned (owner in the create call, doc-confirmed
  // optional) gets its assignment row too, so the owner->task map is seeded even
  // when no TaskUpdate ever reassigns it.
  if (ti.owner) emit(contextDir, { task: id, event: 'assigned', session, owner: ti.owner });
}

function onTaskUpdate(contextDir, session, ti, tr) {
  const id = ti.taskId || null;
  if (!id) return;
  const owner = ti.owner || null;
  // The status IS the event (design event vocabulary: in_progress | completed |
  // blocked | ...). Prefer the authoritative transition target from the result;
  // fall back to the requested status in the input.
  const status = (tr.statusChange && tr.statusChange.to) || ti.status || null;
  if (status) {
    emit(contextDir, { task: id, event: status, session, owner });
  } else if (owner) {
    // Owner-only update = a (re)assignment; record it so the map has the binding.
    emit(contextDir, { task: id, event: 'assigned', session, owner });
  }
}

function onSendMessage(contextDir, session, ti, tr) {
  const to = ti.to || null;
  if (!to) return;
  if (tr && tr.success === false) return; // undelivered message woke nobody
  const map = ownerTaskMap(taskLedgerPath(contextDir));
  const task = map[to];
  if (!task) return; // message to a non-owner (coordination chatter): nothing to log
  emit(contextDir, { task, event: 'woken', session, owner: to });
}

// --- the owner -> current-task-id join (spike §2) --------------------------

// Rebuild the owner -> most-recent-owned-task-id map from the durable ledger.
// The ledger is append-only and chronological, so a later `owner=X task=Y` row
// wins. Only rows that carry BOTH owner= and task= contribute (created rows
// without an owner, and coordination rows, are skipped). Reading the file each
// time (rather than an in-process cache) is correct here: every hook invocation
// is a fresh short-lived process, so the ledger IS the shared state.
function ownerTaskMap(ledgerPath) {
  const map = {};
  let text;
  try { text = fs.readFileSync(ledgerPath, 'utf8'); } catch { return map; }
  for (const line of text.split('\n')) {
    if (!line.trim()) continue;
    // The optional subject= field is always LAST and is JSON-quoted (may itself
    // contain "task=" / "owner=" text), so scan only the head of the line.
    const head = line.split(' subject=')[0];
    const ownerM = /(?:^|\s)owner=(\S+)/.exec(head);
    const taskM = /(?:^|\s)task=(\S+)/.exec(head);
    if (ownerM && taskM) map[ownerM[1]] = taskM[1];
  }
  return map;
}

// --- record.cjs plumbing ---------------------------------------------------

function taskLedgerPath(contextDir) {
  return path.join(contextDir, 'task-ledger.md');
}

// Locate the pinned, self-contained appender. Prefer the scaffold path under the
// project root; fall back to the layout relative to this hook (.claude/hooks ->
// .claude/bmad/bin). Mirrors replay-gate.cjs's resolver.
function findRecordCjs(contextDir) {
  const projectRoot = path.resolve(contextDir, '..', '..');
  const candidates = [
    path.join(projectRoot, '.claude', 'bmad', 'bin', 'record.cjs'),
    path.join(__dirname, '..', 'bmad', 'bin', 'record.cjs'),
  ];
  return candidates.find((c) => fs.existsSync(c)) || null;
}

// Append one task-ledger row through the serialized CLI (lock + atomic). Every
// field is optional except task+event; the CLI formats the line and stamps the
// wall-clock timestamp itself (there is no timestamp in the PostToolUse payload).
function emit(contextDir, row) {
  const recordCjs = findRecordCjs(contextDir);
  if (!recordCjs) return; // no appender installed: advisory row is simply lost
  const args = [recordCjs, 'task-event', '--task', String(row.task), '--event', String(row.event),
    '--context-dir', contextDir];
  if (row.owner) args.push('--owner', String(row.owner));
  if (row.session) args.push('--session', String(row.session));
  if (row.detail) args.push('--detail', String(row.detail));
  try {
    spawnSync('node', args, { encoding: 'utf8', timeout: 15000 });
  } catch { /* best-effort: the tool already succeeded; the row is advisory */ }
}
